import{_ as t,o,c as a,a2 as d}from"./chunks/framework.LX5S0jbT.js";const p=JSON.parse('{"title":"Customize Pi with themes","description":"","frontmatter":{},"headers":[],"relativePath":"themes.md","filePath":"themes.md"}'),s={name:"themes.md"};function r(i,e,n,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="customize-pi-with-themes" tabindex="-1">Customize Pi with themes <a class="header-anchor" href="#customize-pi-with-themes" aria-label="Permalink to &quot;Customize Pi with themes&quot;">​</a></h1><p>Themes control the colors Pi uses in interactive mode and HTML exports. Pi includes the <code>system</code>, <code>dark</code>, and <code>light</code> themes. You can select one theme, follow your terminal&#39;s light or dark appearance, or create your own palette.</p><h2 id="use-your-terminal-s-colors" tabindex="-1">Use your terminal&#39;s colors <a class="header-anchor" href="#use-your-terminal-s-colors" aria-label="Permalink to &quot;Use your terminal&#39;s colors&quot;">​</a></h2><p>The <code>system</code> theme is the default. It builds Pi&#39;s colors from your terminal&#39;s theme, so Pi matches the terminal instead of bringing its own palette:</p><ul><li>Pi queries the terminal&#39;s default foreground and background colors and its 16 ANSI colors.</li><li>Each Pi color takes its hue from one ANSI color, for example errors from red and links from blue.</li><li>Pi sets each color&#39;s lightness so that it stands out from the background by a minimum contrast. Body text keeps at least a 4.5:1 WCAG contrast ratio on the background and every panel.</li><li>When the terminal switches between light and dark, Pi queries the colors again and rebuilds the theme.</li></ul><p>The theme adapts to what the terminal reports:</p><table tabindex="0"><thead><tr><th>Terminal reports</th><th>Result</th></tr></thead><tbody><tr><td>Background and ANSI colors</td><td>Colors from the terminal palette, placed for the actual background.</td></tr><tr><td>Background only</td><td>Pi&#39;s own hues, placed for the actual background.</td></tr><tr><td>Nothing</td><td>ANSI color indices and the terminal&#39;s default colors, which the terminal renders itself. Secondary text is faint, and panels have no background color.</td></tr></tbody></table><p>Pi asks the terminal for its colors when it starts. Terminals usually answer within a few milliseconds, and Pi waits at most 100 ms before showing the startup header. If the terminal does not answer in time, Pi uses the ANSI color fallback, and it still applies the colors if they arrive later, for example over a slow SSH connection. <code>system</code> is a reserved name: a custom theme with that name is ignored.</p><p><a id="selecting-a-theme"></a></p><h2 id="choose-a-theme" tabindex="-1">Choose a theme <a class="header-anchor" href="#choose-a-theme" aria-label="Permalink to &quot;Choose a theme&quot;">​</a></h2><p>Open <code>/settings</code> and select <strong>Theme</strong>. You can use one theme for every terminal appearance or choose separate themes for light and dark terminals.</p><p>The selection is saved as the <code>theme</code> <a href="./settings.html#terminal-and-display">setting</a>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;theme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dark&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Without a <code>theme</code> setting, Pi uses <code>system</code>.</p><p>Automatic mode stores the light theme first and the dark theme second:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;theme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;light/dark&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Pi decides whether the terminal is light or dark from its reported background and foreground colors. If the terminal does not report its background, Pi uses the terminal&#39;s light/dark notification, then the <code>COLORFGBG</code> environment variable, then dark. The same decision picks the theme of a light/dark pair and the appearance of <code>system</code>. When automatic mode is active, Pi changes themes when the terminal reports an appearance change. Theme names cannot contain <code>/</code> because Pi reserves it for this setting format.</p><p>Use <code>--use-theme</code> to choose the initial theme for one invocation without changing the saved setting:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --use-theme</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> light</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --use-theme</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> light/dark</span></span></code></pre></div><p>See <a href="./cli.html#resources">CLI resources</a> for the command-line option.</p><h2 id="create-a-custom-theme" tabindex="-1">Create a custom theme <a class="header-anchor" href="#create-a-custom-theme" aria-label="Permalink to &quot;Create a custom theme&quot;">​</a></h2><p>Copy one of the <a href="https://github.com/earendil-works/pi/tree/main/packages/coding-agent/src/modes/interactive/theme" target="_blank" rel="noreferrer">built-in themes</a> or create a new JSON file conforming to the <a href="https://pi.dev/schemas/theme.schema.json" target="_blank" rel="noreferrer">schema</a>. The built-in themes use OKHSL colors, with variables for colors that several roles share, so you can adjust a hue, saturation, or lightness directly.</p><ol><li>Save the file as <code>&lt;agent-dir&gt;/themes/my-theme.json</code>. The agent directory defaults to <code>~/.pi/agent</code>.</li><li>Set its <code>name</code> to <code>my-theme</code>.</li><li>Change values in <code>vars</code> and <code>colors</code>.</li><li>Select <code>my-theme</code> through <code>/settings</code>.</li></ol><p>Use the theme name as the filename. Pi hot-reloads the active user theme only from <code>&lt;agent-dir&gt;/themes/&lt;name&gt;.json</code>. Run <code>/reload</code> after adding or changing a theme from any other source.</p><h2 id="understand-the-theme-file" tabindex="-1">Understand the theme file <a class="header-anchor" href="#understand-the-theme-file" aria-label="Permalink to &quot;Understand the theme file&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Required</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>$schema</code></td><td>No</td><td>Enables editor validation and completion against Pi&#39;s published schema.</td></tr><tr><td><code>name</code></td><td>Yes</td><td>Identifies the theme in selectors and settings. It must be unique, cannot contain <code>/</code>, and cannot be <code>system</code>.</td></tr><tr><td><code>appearance</code></td><td>No</td><td><code>&quot;dark&quot;</code> or <code>&quot;light&quot;</code>: the background the theme is designed for. Pi detects it from the theme colors when omitted.</td></tr><tr><td><code>vars</code></td><td>No</td><td>Defines reusable color values. Variables can reference other variables.</td></tr><tr><td><code>colors</code></td><td>Yes</td><td>Assigns colors to terminal UI roles. The schema identifies required and optional roles.</td></tr><tr><td><code>export</code></td><td>No</td><td>Overrides page and panel backgrounds in HTML exports.</td></tr></tbody></table><p>Theme objects are strict: only documented top-level fields and color tokens are accepted. Define reusable custom colors under <code>vars</code>; custom keys under <code>colors</code> or <code>export</code> and additional top-level metadata are rejected.</p><p>A color can be written in six forms:</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td>RGB hexadecimal</td><td><code>&quot;#0af&quot;</code> or <code>&quot;#00aaff&quot;</code></td><td>A three- or six-digit sRGB color.</td></tr><tr><td>OKLCH</td><td><code>&quot;oklch(62% 0.1 200)&quot;</code></td><td>Perceptual lightness, chroma, and hue.</td></tr><tr><td>OKHSL</td><td><code>&quot;okhsl(250 60% 55%)&quot;</code></td><td>Hue, saturation, and lightness. Saturation is relative to the most the sRGB gamut allows at that hue and lightness, so every value is in gamut and equal saturation looks equally colorful.</td></tr><tr><td>256-color index</td><td><code>39</code></td><td>An ANSI palette index from <code>0</code> through <code>255</code>.</td></tr><tr><td>Variable reference</td><td><code>&quot;primary&quot;</code></td><td>The value of an entry in <code>vars</code>.</td></tr><tr><td>Terminal default</td><td><code>&quot;&quot;</code></td><td>The terminal&#39;s default foreground or background color.</td></tr></tbody></table><p>Terminal default colors render as the terminal&#39;s own colors. Where Pi needs a concrete value, such as HTML export or extension color math, it uses the default colors the terminal reports, or a black or white guess based on the theme&#39;s appearance.</p><p>Pi resolves chained variable references. A missing variable or circular reference makes the theme invalid. Pi uses truecolor when available, gamut-maps OKLCH to sRGB, and approximates colors for 256-color terminals. HTML exports convert OKHSL values to hexadecimal because CSS does not support them. If colors differ from their source values, check your terminal&#39;s truecolor detection and contrast settings. See <a href="./terminal-setup.html#override-detected-capabilities">Configure Your Terminal</a>.</p><p>Use the <a href="https://pi.dev/schemas/theme.schema.json" target="_blank" rel="noreferrer">theme JSON schema</a> for the exact properties, required colors, and accepted value types.</p><p>Pi reports invalid theme files during startup and <code>/reload</code>.</p><h2 id="find-the-color-to-change" tabindex="-1">Find the color to change <a class="header-anchor" href="#find-the-color-to-change" aria-label="Permalink to &quot;Find the color to change&quot;">​</a></h2><p>Theme colors describe interface roles rather than individual components. Use these groups to find the relevant part of the schema:</p><table tabindex="0"><thead><tr><th>Area</th><th>Color names</th></tr></thead><tbody><tr><td>General interface</td><td><code>accent</code>, <code>border*</code>, <code>text</code>, <code>muted</code>, <code>dim</code>, <code>success</code>, <code>error</code>, <code>warning</code></td></tr><tr><td>Selection and fullscreen</td><td><code>selectedBg</code>, <code>searchMatch*</code>, <code>scrollbar*</code></td></tr><tr><td>Messages</td><td><code>userMessage*</code>, <code>customMessage*</code>, <code>thinkingText</code></td></tr><tr><td>Tool execution</td><td><code>toolPendingBg</code>, <code>toolSuccessBg</code>, <code>toolErrorBg</code>, <code>toolTitle</code>, <code>toolOutput</code></td></tr><tr><td>Markdown</td><td><code>md*</code></td></tr><tr><td>Tool diffs</td><td><code>toolDiff*</code></td></tr><tr><td>Syntax highlighting</td><td><code>syntax*</code></td></tr><tr><td>Editor modes</td><td><code>thinking*</code>, <code>bashMode</code></td></tr><tr><td>HTML export</td><td><code>export.pageBg</code>, <code>export.cardBg</code>, <code>export.infoBg</code></td></tr></tbody></table><p>The schema is the format reference. The built-in themes provide complete values that you can copy and adjust.</p><p>Five colors are optional and inherit another color when omitted:</p><table tabindex="0"><thead><tr><th>Optional color</th><th>Fallback</th></tr></thead><tbody><tr><td><code>scrollbarTrack</code></td><td><code>muted</code></td></tr><tr><td><code>scrollbarThumb</code></td><td><code>text</code></td></tr><tr><td><code>searchMatchBg</code></td><td><code>selectedBg</code></td></tr><tr><td><code>searchMatchText</code></td><td><code>text</code></td></tr><tr><td><code>thinkingMax</code></td><td><code>thinkingXhigh</code></td></tr></tbody></table><p>If <code>export</code> colors are omitted, Pi derives HTML page and panel backgrounds from <code>userMessageBg</code>.</p><h2 id="load-a-theme-from-a-project-or-package" tabindex="-1">Load a theme from a project or package <a class="header-anchor" href="#load-a-theme-from-a-project-or-package" aria-label="Permalink to &quot;Load a theme from a project or package&quot;">​</a></h2><p>Place a project theme in <code>.pi/themes/</code>. Project themes load only after <a href="./security.html#understand-project-trust">project trust</a> is granted.</p><p>You can also load theme files and directories through the <code>themes</code> setting or distribute them in a Pi package. See <a href="./configuration.html">Configuration</a>, <a href="./settings.html#resources">Settings</a>, and <a href="./packages.html">Pi Packages</a>.</p><p>Each loaded theme must have a unique name. Pi reports duplicate names as resource collisions.</p>`,44)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
